begin for pass in 1..2 loop for x in(select OBJECT_NAME,OBJECT_TYPE from USER_OBJECTS where STATUS='INVALID'and OBJECT_NAME in('RRL_ASSEMBLY_SCALE_API','RRL_INTERWARE_INCIDENT_API','RRL_SAP_STORE_ADMISSION_API','RRL_STOCK_METADATA_TX','RRL_STORE_CALENDAR_API','RRL_ST_DEFER_API','RRL_ST_DEFER_WAIT_API','RRL_TT_ROUTE_API','RRL_TT_TIME_API','RRL_UPDATE_PALLET_ROW2','RRL_UPDATE_PALLET_ROW3','RRL_WARE_DEPOT_API','RRL_WAVE_TIME_API','RRL_WORKLOAD_CONFIG_API'))loop if x.OBJECT_TYPE='PACKAGE BODY'then execute immediate 'alter package '||dbms_assert.simple_sql_name(x.OBJECT_NAME)||' compile body';elsif x.OBJECT_TYPE='FUNCTION'then execute immediate 'alter function '||dbms_assert.simple_sql_name(x.OBJECT_NAME)||' compile';end if;end loop;end loop;end;
/
